import { readFileSync } from 'node:fs';
import { E2E_SECRETS_FILE } from './env';

/**
 * Read-only access to the generated E2E credentials.
 *
 * Passwords and TOTP secrets are generated by `e2e:seed`/`e2e:reset` and
 * written to a 0600 file OUTSIDE the repository. They are read here and used,
 * but never embedded in a spec or a snapshot.
 */

export interface E2EUserSecret {
    name: string;
    password: string;
    totp_secret: string | null;
    has_two_factor: boolean;
    approval_status: string;
    account_status: string;
}

export interface E2EInviteLinkSecret {
    token: string;
    household: string;
}

export interface E2ESecrets {
    generated_at: string;
    users: Record<string, E2EUserSecret>;
    households: { alpha: string; beta: string };
    invite_links: Record<'valid' | 'expired' | 'exhausted' | 'revoked', E2EInviteLinkSecret>;
}

export function readSecrets(): E2ESecrets {
    return JSON.parse(readFileSync(E2E_SECRETS_FILE, 'utf8')) as E2ESecrets;
}

export function userSecret(email: string): E2EUserSecret {
    const user = readSecrets().users[email];

    if (! user) {
        throw new Error(`No E2E fixture is seeded for ${email}. Run \`php artisan e2e:seed\`.`);
    }

    return user;
}
